insert into public.questions (status, category, board, situation, question, answer, answered_at, created_at) values ('published', 'prep', 'prep', '재학생', '3학년입니다. 지금 뭘 가장 먼저 해야 하나요?', '토익이나 자격증보다 "회사"가 아니라 "직무"를 먼저 정하세요. 공채 시대의 ''공통 스펙''은 수시채용에서 변별력이 거의 없습니다. 순서는 ① Job Title 결정(데이터 분석가 · HR · 마케터 등 하나로 명확히) ② 그 직무의 채용공고 10개를 모아 공통 자격요건 추출 ③ 요건 대비 나에게 부족한 것 리스트업 — 이것이 To-Do ④ 그 직무를 잘 키워줄 회사를 규모 불문 후보군으로 정리. 반대로 "삼성 · 네이버 · 카카오 가고 싶다"처럼 회사만 정하면 회사마다 뽑는 직무가 달라 준비가 분산되고, 면접에서 "왜 이 직무인가"에 답하지 못합니다. 채용담당자는 그 공백을 가장 먼저 알아봅니다.', now() - interval '1 days', now() - interval '1 days');
insert into public.questions (status, category, board, situation, question, answer, answered_at, created_at) values ('published', 'linkedin', 'prep', '취준생 · 이직', '신입인데 링크드인이 정말 필요한가요?', '네. 지금 기업 채용의 큰 축은 다이렉트 소싱(채용담당자가 직접 후보자를 찾는 것)입니다. 인터엑스도 서치펌 의존을 줄이고 다이렉트 소싱 비중을 80% 이상으로 올렸습니다. 채용담당자는 직무 키워드로 검색하고 헤드라인·About을 보고 클릭합니다. 헤드라인에 "취준생" 대신 지원 직무와 핵심 스킬을 쓰고, 프로젝트·인턴 경험을 경력란에 성과 중심으로 적어두면 신입도 연락이 옵니다.', now() - interval '2 days', now() - interval '2 days');
insert into public.questions (status, category, board, situation, question, answer, answered_at, created_at) values ('published', 'interview', 'prep', '취준생 · 이직', '면접에서 1분 자기소개는 어떻게 해야 하나요?', '자기소개는 ''나를 설명하는 시간''이 아니라 "이 포지션에 내가 맞는 이유를 3가지로 예고하는 시간"입니다. 구조는 ① 지원 직무와 연결되는 한 줄 정체성 ② 공고의 핵심 요건에 대응하는 경험 2~3개를 숫자와 함께 ③ 이 회사·포지션에서 하고 싶은 것. 면접관은 자기소개에서 꺼낸 키워드로 다음 질문을 던지니, 내가 준비된 경험으로 유도하는 것이 핵심입니다.', now() - interval '3 days', now() - interval '3 days');
insert into public.questions (status, category, board, situation, question, answer, answered_at, created_at) values ('published', 'interview', 'prep', '역량 면접', '역량 기반 면접은 어떻게 준비하나요?', '면접관은 "과거에 어떻게 행동했는가"로 미래를 예측합니다. 내 경험을 상황(S) – 과제(T) – 행동(A) – 결과(R)로 정리한 카드 5~7장이면 대부분의 질문을 덮을 수 있습니다. 중요한 건 ''행동''과 ''결과''의 비중입니다. 상황 설명이 길어지면 떨어집니다. 결과는 가능한 숫자로, 숫자가 없으면 전후 비교로 말하세요.', now() - interval '4 days', now() - interval '4 days');
insert into public.questions (status, category, board, situation, question, answer, answered_at, created_at) values ('published', 'job', 'job', '헤드헌터', '헤드헌터 연락이 왔는데, 어떻게 대해야 하나요?', '헤드헌터는 ''나를 파는 사람''이 아니라 기업의 의뢰를 채우는 사람입니다. 그래서 내 조건보다 그 포지션 요건에 맞는지를 봅니다. 당장 이직 생각이 없어도 정중하게 연결을 유지하고, 내 희망 직무·연봉·근무지를 명확히 알려두세요. 좋은 헤드헌터는 1~2년 뒤 딱 맞는 포지션을 들고 다시 옵니다. 단, 이력서를 동의 없이 여러 회사에 뿌리는 헤드헌터는 거르세요.', now() - interval '5 days', now() - interval '5 days');
insert into public.questions (status, category, board, situation, question, answer, answered_at, created_at) values ('published', 'job', 'job', '이직', '연봉협상, 얼마를 불러야 하나요?', '원칙 세 가지. ① 숫자를 먼저 말하지 말고 현재 연봉(원천징수 기준)과 희망 범위를 물어볼 때 답하세요. ② 희망은 ''범위''로, 하한은 내가 실제로 받아들일 수 있는 숫자여야 합니다. ③ 기본급 외에 사이닝 보너스, 성과급, 스톡옵션, 직급을 같이 테이블에 올리세요. 채용담당자도 오퍼 수락률이 KPI라 합리적인 요구는 들어줄 여지가 큽니다. 오퍼 레터 받기 전 구두 합의 내용은 반드시 메일로 남기세요.', now() - interval '6 days', now() - interval '6 days');
insert into public.questions (status, category, board, situation, question, answer, answered_at, created_at) values ('published', 'job', 'job', '평판조회', '평판조회(레퍼런스 체크)는 정말 하나요? 뭘 물어보나요?', '경력직은 대부분 합니다. 묻는 건 주로 ① 함께 일한 기간과 역할이 이력서와 맞는지 ② 강점과 보완점 ③ 다시 같이 일하고 싶은지. 그래서 이직 사유를 전 직장 욕으로 만들면 안 됩니다. 평판은 퇴사하는 날이 아니라 재직 중에 만들어집니다. 레퍼런스로 세울 상사·동료 2~3명을 미리 정하고 양해를 구해두세요.', now() - interval '7 days', now() - interval '7 days');
insert into public.questions (status, category, board, situation, question, answer, answered_at, created_at) values ('published', 'foreign', 'prep', '영문 서류', '외국계 기업은 영어를 얼마나 잘해야 하나요?', '포지션마다 다릅니다. 공고의 Job Description에 "fluent", "business level", "preferred" 중 어떤 표현이 쓰였는지 보세요. 대부분의 국내 외국계 포지션은 ''영어로 메일 쓰고 글로벌 미팅에서 내 업무를 설명할 수 있는 수준''이면 됩니다. 영어 인터뷰는 자기소개와 핵심 경험 3개를 영어 STAR로 미리 써서 소리 내어 연습하는 것만으로도 체감 난이도가 크게 내려갑니다.', now() - interval '8 days', now() - interval '8 days');
insert into public.questions (status, category, board, situation, question, answer, answered_at, created_at) values ('published', 'prep', 'prep', '대학원 · 자격증', '취업이 안 돼서 대학원을 갈까 고민입니다.', '"취업이 안 돼서"가 이유라면 말리고 싶습니다. 석사는 연구·전문직 트랙(R&D, 데이터, 특정 전문직)에서 요건이 될 때 가치가 있고, 그 외 직무에서는 2년 늦은 신입이 됩니다. 지원 직무의 채용공고 20개를 모아 ''석사 우대''가 몇 개인지 세어보세요. 절반 미만이면 대학원 대신 인턴·계약직으로 실무 경험을 만드는 게 훨씬 빠릅니다.', now() - interval '9 days', now() - interval '9 days');
insert into public.questions (status, category, board, situation, question, answer, answered_at, created_at) values ('published', 'docs', 'prep', '영문 이력서', '영문 Resume는 국문 이력서를 번역하면 되나요?', '아니요. 구조가 다릅니다. 영문 Resume는 1페이지, 사진·생년월일·가족사항 없음, 가장 위에 Summary 3줄, 경력은 동사로 시작하는 성과 불릿("Reduced … by 30%"), 학력은 아래. 한국식 ''담당 업무 나열''을 그대로 번역하면 외국계 채용담당자에게는 아무 것도 한 게 없는 사람으로 읽힙니다.', now() - interval '10 days', now() - interval '10 days');
insert into public.questions (status, category, board, situation, question, answer, answered_at, created_at) values ('published', 'prep', 'prep', '첫 직장', '대기업 준비와 스타트업 · 외국계 지원을 병행해도 되나요?', '대기업 · 스타트업 · 외국계는 "직무"가 같다면 병행할 수 있습니다. 준비의 중심이 직무 경쟁력(실무 경험 · 영어 회화 · AI 활용)이기 때문입니다. 다만 대기업만 바라보고 2~3년을 소진하는 것이 가장 위험합니다. 대기업은 "목표"가 아니라 여러 선택지 중 하나로 두세요. 반대로 공기업은 병행이 아니라 선택입니다. NCS 트랙과 직무 트랙은 준비 방식이 달라 어중간한 병행은 둘 다 놓치기 쉽습니다. 6개월 안에 방향을 정하세요.', now() - interval '11 days', now() - interval '11 days');
insert into public.questions (status, category, board, situation, question, answer, answered_at, created_at) values ('published', 'prep', 'prep', '경력 없음', '인턴마저 경력을 보고 뽑는 시기에, 아무 경력이 없는 지원자에게도 길이 있을까요?', '있습니다. 채용 현장에서 검증된 3단계 우회 전략입니다. ① 진입장벽 낮은 곳부터 — 직무 · 기업의 눈높이를 전략적으로 낮춰 인턴 · 계약직 · 파견직으로 우선 진입 ② 2년, 실무 레퍼런스 — 지원 직무와 연결된 실무 경험을 2년 축적 ③ 원하는 곳으로 이직 — 쌓은 경험을 무기로 목표 직무 · 기업으로 전략적 이직. 경력 채용 담당자는 "정규직이었는가"보다 "무슨 일을 해봤는가"를 봅니다. 외국계 · 대기업의 상당수 정규직이 실제로 이 경로로 채워집니다.', now() - interval '12 days', now() - interval '12 days');
insert into public.questions (status, category, board, situation, question, answer, answered_at, created_at) values ('published', 'prep', 'prep', '계약직', '신입은 계약직으로 들어가도 괜찮을까요?', '지원 직무와 연결된 일이라면 괜찮습니다. 백지 상태로 정규직 공고만 기다린 2년과, 계약직으로라도 실무를 채운 2년 — 이력서의 무게는 완전히 다릅니다. 특히 외국계는 공채가 없어 인턴 · 계약직 → 정규직 전환이 왕도입니다. GE에서 뽑은 신입 대부분이 이 경로였습니다. 단, 직무와 무관한 단순 업무 계약직은 경력으로 인정받기 어려우니 "무슨 일을 하게 되는가"를 꼭 확인하세요.', now() - interval '13 days', now() - interval '13 days');
insert into public.questions (status, category, board, situation, question, answer, answered_at, created_at) values ('published', 'prep', 'prep', 'AI 시대', 'AI 때문에 신입 채용이 줄어든다는데, 진짜인가요?', '''단순 반복 업무를 할 신입''은 줄고, ''AI를 써서 시니어와 짝을 이룰 신입''은 늘고 있습니다. 인터엑스는 AI 전문 신입·인턴과 시니어 직무 전문가를 짝짓는 하이브리드 구조로 인턴을 뽑고, 입사 4개월 차 인턴이 AI 채용 시스템 구축을 주도한 사례도 있습니다. 지원 직무에서 생성형 AI로 무엇을 자동화·개선해 봤는지 한 가지 사례를 만들어 두세요. 2026년 채용에서 가장 확실한 차별점입니다.', now() - interval '14 days', now() - interval '14 days');
